$(document).ready((function(){function animateProgressBar(){$(".dina_progress_bar_child .dina_progress_bar-item").each((function(){const percent=$(this).find(".dina_progress-level").data("per"),rect=$(this).offset(),scrollTop=$(window).scrollTop(),windowHeight=$(window).height();rect.top+$(this).height()>=scrollTop&&rect.top<=scrollTop+windowHeight&&$(this).find(".dina_progress-level").css({width:percent})}))}animateProgressBar(),$(window).scroll((function(){animateProgressBar()}))}));